#!/usr/bin/env bash
# apply_watchall_pr.sh — bot v4.5.1 + worker Watch-ALL mode (2 repos, PR-first)
# Run from anywhere:  bash apply_watchall_pr.sh
set -u
fail() { echo "✗ $*" >&2; exit 1; }
BOT_B64=""
BOT_SHA="557c40ae775050463dfe8d9cceaf72bf153102d4381a99f63899d5c35ccafb12"
WRK_B64=""
WRK_SHA="3760bd2fdda919c0b519f650d619a2492bc919249ea6402e97a30b91e0b3b6b0"

echo '═══════ 1/2: ftt-telegram-bot ═══════'
cd ~/ftt-telegram-bot || fail '~/ftt-telegram-bot not found'
git fetch --quiet origin 2>/dev/null
[ "$(git rev-parse --abbrev-ref HEAD)" = 'main' ] || fail 'bot not on main'
[ -z "$(git status --porcelain)" ] || fail 'bot working tree not clean'
grep -q 'FTT Signal Bot v4.5.0' src/index.js || fail 'bot not at v4.5.0 — repo differs'
printf '%s' "$BOT_B64" | base64 -d > $HOME/watchall_bot.patch
[ "$(sha256sum $HOME/watchall_bot.patch | cut -d' ' -f1)" = "$BOT_SHA" ] || fail 'bot patch sha mismatch'
git apply --check $HOME/watchall_bot.patch || fail 'bot git apply --check failed'
git apply $HOME/watchall_bot.patch && rm -f $HOME/watchall_bot.patch
grep -q 'DOT/USD' src/index.js || fail 'bot: DOT/USD missing after apply'
grep -q 'watchAll' src/index.js || fail 'bot: watchAll missing after apply'
node --check src/index.js || fail 'bot syntax'
node menu-test.mjs 2>&1 | grep -q 'ALL MENU TESTS PASSED' || fail 'menu-test'
node round2-bugfix-test.mjs 2>&1 | grep -q 'ALL BUGFIX + INTEGRATION TESTS PASSED' || fail 'round2 test'
node single-source-test.mjs 2>&1 | grep -q 'ALL SINGLE-SOURCE-OF-TRUTH TESTS PASSED' || fail 'single-source test'
echo '  ✓ bot v4.5.1 verified'
git checkout -b feat/watch-all
git add src/index.js
git commit -m 'feat: Watch-ALL mode + add DOT/USD, LINK/USD pairs (v4.5.1)' || fail 'bot commit failed'
git push -u origin feat/watch-all || fail 'bot push failed'

echo '═══════ 2/2: Ftt-Otc-v6 ═══════'
cd ~/Ftt-Otc-v6 || fail '~/Ftt-Otc-v6 not found'
git fetch --quiet origin 2>/dev/null
[ "$(git rev-parse --abbrev-ref HEAD)" = 'main' ] || fail 'worker not on main'
[ -z "$(git status --porcelain)" ] || fail 'worker working tree not clean'
grep -q 'if (!watched.includes(want))' src/handlers/pushToSubscribers.js || fail 'worker baseline differs'
printf '%s' "$WRK_B64" | base64 -d > $HOME/watchall_worker.patch
[ "$(sha256sum $HOME/watchall_worker.patch | cut -d' ' -f1)" = "$WRK_SHA" ] || fail 'worker patch sha mismatch'
git apply --check $HOME/watchall_worker.patch || fail 'worker git apply --check failed'
git apply $HOME/watchall_worker.patch && rm -f $HOME/watchall_worker.patch
grep -q 'watchAll' src/handlers/pushToSubscribers.js || fail 'worker: watchAll missing'
OUT=$(node scripts/fix_tests.mjs 2>&1 | tail -n 2); echo "$OUT"
echo "$OUT" | grep -q 'PASS: 326' || fail 'worker fix_tests not 326/0'
echo '  ✓ worker verified (fix_tests 326/0)'
git checkout -b feat/watch-all
git add src/handlers/pushToSubscribers.js scripts/fix_tests.mjs
git commit -m 'feat: Watch-ALL mode — pair gate bypass when user.watchAll (v4.5.1)' || fail 'worker commit failed'
git push -u origin feat/watch-all || fail 'worker push failed'

echo ''
echo '═══ DONE ═══'
echo 'Bot PR   : https://github.com/ferdausfs/ftt-telegram-bot/compare/feat/watch-all'
echo 'Worker PR: https://github.com/ferdausfs/Ftt-Otc-v6/compare/feat/watch-all'
echo 'PR body  : ~/Workplace-drive-/pr/PR_BODY_watchall.md'
echo 'Deploy after merge: worker bundle + bot bundle (bot_deploy2.sh)'
